      {
        "id": "src:CSA-RAD-2026-01",
        "label": "CSA-RAD-2026-01",
        "type": "EvidenceSource",
        "title": "Monitoring Radiation for Astronaut Health",
        "organization": "Canadian Space Agency (CSA)",
        "url": "https://www.asc-csa.gc.ca/eng/news/articles/2026/2026-02-26-monitoring-radiation-astronaut-health.asp",
        "summary": "The Canadian Space Agency highlights the critical role of personal and area radiation dosimeters in tracking cosmic ionizing radiation. Microgravity and radiation act synergistically on cellular repair, cardiovascular endothelium, and immune response, mandating strict cumulative dose tracking."
      },
      {
        "id": "src:CSA-SCI-2026-01",
        "label": "CSA-SCI-2026-01",
        "type": "EvidenceSource",
        "title": "Why Do We Conduct Science Experiments in Space?",
        "organization": "Canadian Space Agency (CSA)",
        "url": "https://www.asc-csa.gc.ca/eng/iss/science/why-do-we-conduct-science-experiments-in-space.asp",
        "summary": "Research in microgravity allows scientists to isolate gravity's effects on human physiology, providing invaluable insights into aging, vascular stiffness, and cardiovascular adaptation that inform health protocols both in space and on Earth."
      },
      {
        "id": "src:NASA-HRP-HAZ-01",
        "label": "NASA-HRP-HAZ-01",
        "type": "EvidenceSource",
        "title": "5 Hazards of Human Spaceflight: Altered Gravity Fields & Distance from Earth",
        "organization": "NASA Human Research Program (HRP)",
        "url": "https://www.nasa.gov/hrp/hazards/",
        "summary": "NASA identifies altered gravity fields (0g microgravity, partial-g planetary surfaces, and return to 1g Earth) and distance from Earth as critical human spaceflight hazards. Gravity transitions induce fluid shifts toward the head, decrease total circulating blood volume, and lead to cardiovascular deconditioning."
      },
      {
        "id": "src:NASA-HRP-RES-01",
        "label": "NASA-HRP-RES-01",
        "type": "EvidenceSource",
        "title": "Ongoing HRP Research in Space: Longitudinal Cardiovascular & Vascular Monitoring",
        "organization": "NASA Human Research Program (HRP)",
        "url": "https://www.nasa.gov/hrp/ongoing-hrp-research/",
        "summary": "HRP investigates continuous and longitudinal cardiovascular tracking to understand arterial stiffness, cardiac atrophy, and vascular remodeling across mission phases. In-flight countermeasures such as lower body negative pressure (LBNP) and resistive exercise help mitigate vascular deconditioning."
      },
      {
        "id": "src:NASA-HRP-RISK-01",
        "label": "NASA-HRP-RISK-01",
        "type": "EvidenceSource",
        "title": "Risks of Human Spaceflight: Orthostatic Intolerance & Cardiovascular Adaptation",
        "organization": "NASA Human Research Program (HRP)",
        "url": "https://www.nasa.gov/hrp/risks/",
        "summary": "Upon re-entering a gravity field following prolonged microgravity, astronauts experience orthostatic intolerance due to cephalad fluid shift during spaceflight, reduced plasma volume, and altered autonomic baroreflex sensitivity. Blood pools in the lower extremities upon standing, causing sudden heart rate acceleration and blood pressure drops."
      }
